(function(){
  var all=document.querySelectorAll("div,section,main,form");
  for(var i=0;i<all.length;i++){
    if(all[i].__vue__){
      var vm=all[i].__vue__;
      var d=vm.$data||{};
      var keys=Object.keys(d);
      var summary={};
      keys.slice(0,30).forEach(function(k){var v=d[k];summary[k]=(v===null||typeof v!=="object")?v:(Array.isArray(v)?"array["+v.length+"]":"obj")});
      return JSON.stringify({tag:all[i].tagName,id:all[i].id,cls:(all[i].className||"").toString().slice(0,40),keys:keys,summary:summary});
    }
  }
  return "NO_VUE_FOUND scanned="+all.length;
})()
